// 知识讲解 · 风格样片。标准分镜：标题 → 要点 → 数据 → 人名条 → 收尾。
// 可照搬：STYLE 取值、card()（圆角卡片与柔和投影）、marker()（荧光笔划重点）、donut()（环形图）、
// numberBadge()（分类色序号）、pushIn()（整屏推入换场），以及 layers() 的分层写法：
// 每个元素在画面坐标里画，pose 只给平移与不透明度，运行时据此做运动模糊。

const STYLE = {
  color: {
    bg: "#F6F3EC", // 暖纸色，长时间看不累
    ink: "#23262E",
    muted: "#6E7380",
    card: "#FFFFFF",
    line: "#E4DFD4",
    marker: "#FFE27A", // 荧光笔，只用来划重点
    cats: ["#3E6FE6", "#F2913D", "#2FA77A"], // 三个分类色，一类一色，全片不换
  },
  font: {
    title: '"MiSans", "HarmonyOS Sans SC", "Source Han Sans SC", "Microsoft YaHei", sans-serif',
    number: '"DIN Next LT Pro", "Bahnschrift", "MiSans", sans-serif',
  },
};

const SCENES = { title: [0, 1.85], list: [1.85, 3.85], data: [3.85, 5.65], name: [5.65, 6.95], end: [6.95, 8] };
const COPY = {
  title: ["把想法变成", "画面"],
  subtitle: "风格样片 · STYLE SAMPLE",
  list: ["统一的配色", "统一的字体", "统一的节奏"],
  data: { value: 87, unit: "%", label: "一次通过率" },
  name: { name: "林一", role: "动效设计师" },
  end: ["一个风格，", "处处一致"],
};

const clamp = (v) => Math.max(0, Math.min(1, v));
const cubicOut = (v) => 1 - Math.pow(1 - clamp(v), 3);
const cubicIn = (v) => clamp(v) ** 3;
const cubicInOut = (v) => { v = clamp(v); return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2; };
const font = (weight, size, family) => `${weight} ${Math.round(size)}px ${family}`;

// 温和：入场 0.5 s cubicOut，离场 0.25 s cubicIn。
function phase(t, [a, b], delay = 0, inDur = 0.5, outDur = 0.25) {
  return { enter: cubicOut((t - a - delay) / inDur), leave: cubicIn((t - (b - outDur)) / outDur), on: t >= a && t < b };
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// 白卡片：小圆角 + 一层很柔的投影，像放在纸上的卡片。
function card(ctx, x, y, w, h, u) {
  ctx.save();
  ctx.shadowColor = "rgba(60,50,30,0.12)";
  ctx.shadowBlur = 24 * u;
  ctx.shadowOffsetY = 8 * u;
  ctx.fillStyle = STYLE.color.card;
  roundRect(ctx, x, y, w, h, 14 * u);
  ctx.fill();
  ctx.restore();
}

// 荧光笔：从左到右划过关键词的下半部分，略微倾斜、两端不齐，像手划的。baseline、size 是被划文字的基线和字号。
function marker(ctx, x, baseline, w, size, k) {
  if (k <= 0) return;
  const y = baseline - size * 0.46, h = size * 0.56;
  ctx.save();
  ctx.fillStyle = STYLE.color.marker;
  ctx.beginPath();
  const len = w * cubicOut(k);
  ctx.moveTo(x - 4, y + h * 0.1);
  ctx.lineTo(x + len, y);
  ctx.lineTo(x + len + 4, y + h);
  ctx.lineTo(x, y + h * 1.05);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function numberBadge(ctx, x, y, r, n, color, u) {
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = "#FFFFFF";
  ctx.font = font(700, r * 1.05, STYLE.font.number);
  ctx.textAlign = "center";
  ctx.fillText(String(n), x, y + r * 0.37);
  ctx.textAlign = "left";
}

// 换场：整屏内容向左推出，新内容从右推入（只在场景开头 0.45 s 内）。
function pushIn(t, a, w) {
  return (1 - cubicInOut((t - a) / 0.45)) * w * 0.12;
}

function donut(ctx, cx, cy, r, k, u) {
  ctx.lineCap = "round";
  ctx.lineWidth = 26 * u;
  ctx.strokeStyle = STYLE.color.line;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.stroke();
  ctx.strokeStyle = STYLE.color.cats[0];
  ctx.beginPath(); ctx.arc(cx, cy, r, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * k); ctx.stroke();
}

const within = (t, [a, b]) => t >= a && t < b;

// 每个元素都在画面坐标里画，pose 只给出平移（换场推移 + 入场上浮）和不透明度，运行时据此做运动模糊。
function layers(_params, w, h) {
  const u = h / 720, C = STYLE.color, F = STYLE.font, out = [];
  out.push({ draw: (ctx) => { ctx.fillStyle = C.bg; ctx.fillRect(0, 0, w, h); } });

  // 标题卡：副标题和标题依次上浮，离场时整组向左淡出；关键词随后被荧光笔划出。
  const title = SCENES.title, tx = w * 0.12, ty = h * 0.5;
  out.push({
    bounds: [tx - 10 * u, ty - 100 * u, tx + 420 * u, ty - 60 * u],
    pose: (t) => {
      if (!within(t, title)) return null;
      const p = phase(t, title);
      return { x: -p.leave * w * 0.06, y: (1 - p.enter) * 12 * u, opacity: 1 - p.leave };
    },
    draw: (ctx) => {
      ctx.fillStyle = C.muted;
      ctx.font = font(500, 18 * u, F.title);
      ctx.fillText(COPY.subtitle, tx, ty - 72 * u);
    },
  });
  out.push({
    bounds: [tx - 10 * u, ty - 70 * u, tx + 520 * u, ty + 24 * u],
    pose: (t) => {
      if (!within(t, title)) return null;
      const p = phase(t, title), pk = phase(t, title, 0.12).enter;
      return { x: -p.leave * w * 0.06, y: (1 - pk) * 20 * u, opacity: pk * (1 - p.leave) };
    },
    draw: (ctx, t) => {
      ctx.font = font(700, 68 * u, F.title);
      const first = ctx.measureText(COPY.title[0]).width, second = ctx.measureText(COPY.title[1]).width;
      marker(ctx, tx + first - 4 * u, ty, second + 8 * u, 68 * u, (t - 0.55) / 0.4);
      ctx.fillStyle = C.ink;
      ctx.fillText(COPY.title[0] + COPY.title[1], tx, ty);
    },
  });

  // 要点：整屏从右推入，三张卡片依次上浮；分类色短条随后展开。
  const list = SCENES.list, cw = 300 * u, ch = 220 * u, gap = 32 * u, x0 = (w - (cw * 3 + gap * 2)) / 2, y0 = h * 0.5 - ch / 2;
  const listOut = (t) => cubicIn((t - (list[1] - 0.25)) / 0.25);
  COPY.list.forEach((item, i) => {
    const x = x0 + i * (cw + gap);
    out.push({
      bounds: [x - 40 * u, y0 - 30 * u, x + cw + 40 * u, y0 + ch + 50 * u],
      pose: (t) => {
        if (!within(t, list)) return null;
        const p = phase(t, list, 0.15 + i * 0.15), o = listOut(t);
        return p.enter > 0 ? { x: pushIn(t, list[0], w) - o * w * 0.06, y: (1 - p.enter) * 30 * u, opacity: p.enter * (1 - o) } : null;
      },
      draw: (ctx, t) => {
        card(ctx, x, y0, cw, ch, u);
        numberBadge(ctx, x + 44 * u, y0 + 52 * u, 22 * u, i + 1, C.cats[i], u);
        ctx.fillStyle = C.ink;
        ctx.font = font(700, 32 * u, F.title);
        ctx.fillText(item, x + 24 * u, y0 + 130 * u);
        // 分类色短条：同一类信息在全片里始终是这个颜色。
        ctx.fillStyle = C.cats[i];
        ctx.fillRect(x + 24 * u, y0 + 160 * u, 40 * u * phase(t, list, 0.15 + i * 0.15).enter, 5 * u);
      },
    });
  });

  // 数据：环形图与计数随整屏推入；结论和解释上浮，结论被荧光笔划出。
  const data = SCENES.data, cx = w * 0.34, cy = h * 0.5, r = 120 * u, lx = w * 0.56, ly = h * 0.47;
  const dataOut = (t) => cubicIn((t - (data[1] - 0.25)) / 0.25);
  out.push({
    bounds: [cx - r - 20 * u, cy - r - 20 * u, cx + r + 20 * u, cy + r + 20 * u],
    pose: (t) => within(t, data) ? { x: pushIn(t, data[0], w) - dataOut(t) * w * 0.06, y: 0, opacity: 1 - dataOut(t) } : null,
    draw: (ctx, t) => {
      const k = cubicOut((t - data[0] - 0.2) / 1.1) * (COPY.data.value / 100);
      donut(ctx, cx, cy, r, k, u);
      ctx.textAlign = "center";
      ctx.fillStyle = C.ink;
      ctx.font = font(500, 76 * u, F.number);
      ctx.fillText(`${Math.round(k * 100)}`, cx - 12 * u, cy + 26 * u);
      ctx.font = font(500, 30 * u, F.number);
      ctx.fillText(COPY.data.unit, cx + 52 * u, cy + 24 * u);
      ctx.textAlign = "left";
    },
  });
  out.push({
    bounds: [lx - 10 * u, ly - 44 * u, lx + 420 * u, ly + 62 * u],
    pose: (t) => {
      if (!within(t, data)) return null;
      const p = phase(t, data, 0.35), o = dataOut(t);
      return p.enter > 0 ? { x: pushIn(t, data[0], w) - o * w * 0.06, y: (1 - p.enter) * 14 * u, opacity: p.enter * (1 - o) } : null;
    },
    draw: (ctx, t) => {
      ctx.font = font(700, 40 * u, F.title);
      marker(ctx, lx - 4 * u, ly, ctx.measureText(COPY.data.label).width + 8 * u, 40 * u, (t - data[0] - 0.7) / 0.4);
      ctx.fillStyle = C.ink;
      ctx.fillText(COPY.data.label, lx, ly);
      ctx.fillStyle = C.muted;
      ctx.font = font(400, 22 * u, F.title);
      ctx.fillText("每 100 个镜头里，87 个不用返工", lx, ly + 48 * u);
    },
  });

  // 人名条：白色小卡片上浮。
  const name = SCENES.name, nx = w * 0.08, ny = h * 0.74, bw = 280 * u, bh = 76 * u;
  out.push({
    bounds: [nx - 40 * u, ny - 30 * u, nx + bw + 40 * u, ny + bh + 50 * u],
    pose: (t) => {
      if (!within(t, name)) return null;
      const p = phase(t, name, 0.1);
      return p.enter > 0 ? { x: 0, y: (1 - p.enter) * 24 * u, opacity: p.enter * (1 - p.leave) } : null;
    },
    draw: (ctx) => {
      card(ctx, nx, ny, bw, bh, u);
      ctx.fillStyle = C.cats[1];
      ctx.beginPath(); ctx.arc(nx + 38 * u, ny + bh / 2, 22 * u, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = "#FFFFFF";
      ctx.font = font(700, 20 * u, F.title);
      ctx.textAlign = "center";
      ctx.fillText(COPY.name.name[0], nx + 38 * u, ny + bh / 2 + 7 * u);
      ctx.textAlign = "left";
      ctx.fillStyle = C.ink;
      ctx.font = font(700, 26 * u, F.title);
      ctx.fillText(COPY.name.name, nx + 76 * u, ny + 36 * u);
      ctx.fillStyle = C.muted;
      ctx.font = font(400, 16 * u, F.title);
      ctx.fillText(COPY.name.role, nx + 76 * u, ny + 58 * u);
    },
  });

  // 收尾：一句话上浮，关键词随后被荧光笔划出。
  const end = SCENES.end;
  out.push({
    bounds: [w * 0.2, h * 0.53 - 60 * u, w * 0.8, h * 0.53 + 20 * u],
    pose: (t) => {
      const e = phase(t, [end[0], 99], 0.05).enter;
      return t >= end[0] && e > 0 ? { x: 0, y: (1 - e) * 16 * u, opacity: e } : null;
    },
    draw: (ctx, t) => {
      ctx.font = font(700, 54 * u, F.title);
      const a = ctx.measureText(COPY.end[0]).width, b = ctx.measureText(COPY.end[1]).width;
      const x = (w - a - b) / 2, y = h * 0.53;
      marker(ctx, x + a - 4 * u, y, b + 8 * u, 54 * u, (t - end[0] - 0.4) / 0.4);
      ctx.fillStyle = C.ink;
      ctx.fillText(COPY.end[0] + COPY.end[1], x, y);
    },
  });
  return out;
}

export default {
  name: "知识讲解 · 样片", kind: "generator", mode: "dynamic",
  nameEnglish: "Explainer · Sample",
  params: [],
  // 动作温和，180° 快门下只有换场推移和上浮时有轻微拖影。
  motionBlur: { shutter: 180 },
  layers,
};
